-- Persistent user-defined display names for Sound History assets.\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS sound_display_names (\n  generation_id TEXT NOT NULL,\n  user_id TEXT NOT NULL,\n  display_name TEXT NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),\n  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,\n  PRIMARY KEY (generation_id, user_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_sound_display_names_user ON sound_display_names(user_id);\n